// ✅ FIXED ADMIN DASHBOARD (React)
// Shows ALL top donors & volunteers sorted, View Badges works, Event Stats works.
// Copy–paste entire file.

import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from './UserProfileCard';

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [eventStatsType, setEventStatsType] = useState(null);
  const [mostActive, setMostActive] = useState(null);
  const [showAllFeedback, setShowAllFeedback] = useState(false);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  // ---------------------- UNIVERSAL LOADER FIXED ----------------------
  const loadData = async (endpoint, setter, expectedField = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || errMsg);
        } catch {
          throw new Error(errMsg);
        }
      }

      const data = await res.json();

      // If specific field exists
      if (expectedField && data[expectedField]) {
        setter(data[expectedField]);
        return;
      }

      // fallback auto-detection
      const fallback = Object.values(data).find((v) => Array.isArray(v));

      if (fallback) setter(fallback);
      else setter(data);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  // ---------------------- MOST ACTIVE NGO ----------------------
  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");
    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to load most active NGO");

      const data = await res.json();
      const pick = data.mostActive || data.most || data.top || data[0] || null;

      setMostActive(Array.isArray(pick) ? pick[0] : pick);
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  // ---------------------- DELETE NGO ----------------------
  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to delete NGO");

      setMsg("NGO removed successfully");
      setNgos((prev) => prev?.filter((n) => n.id !== id));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  // ---------------------- RENDER RESULTS FIXED ----------------------
  const renderResults = (results, type = null) => {
    if (!results) return null;
    const list = Array.isArray(results) ? results : [results];

    // ----------------- TOP VOLUNTEERS / TOP DONORS FIX -----------------
    if (type === "topVolunteers" || type === "topDonors") {
      const sorted = [...list].sort((a, b) => (b.total || 0) - (a.total || 0));

      return sorted.map((item, i) => (
        <div
          key={i}
          style={{
            padding: 12,
            background: i === 0 ? "#fff9c4" : "#fff",
            borderRadius: 8,
            marginBottom: 8,
            border: i === 0 ? "2px solid #ffd700" : "1px solid #ccc",
          }}
        >
          <strong style={{ color: i === 0 ? "#d35400" : "#0d47a1" }}>
            {i === 0 ? "🌟 TOP " : ""}{item.name || item.user_name}
          </strong>
          <div>Total: {item.total}</div>
        </div>
      ));
    }

    // ----------------- BADGES FIX -----------------
    if (type === "badges") {
      return list.map((item, i) => (
        <div
          key={i}
          style={{ padding: 12, background: "#fff", borderRadius: 8, marginBottom: 8, border: "2px solid #ffd700" }}
        >
          <strong>🏆 {item.name}</strong>
          <div>{item.email}</div>
          <div>Badge: {item.badge}</div>
        </div>
      ));
    }

    // ----------------- DEFAULT EVENT STATS -----------------
    return list.map((item, i) => (
      <div
        key={i}
        style={{ padding: 12, background: "#fff", borderRadius: 8, marginBottom: 8 }}
      >
        <pre>{JSON.stringify(item, null, 2)}</pre>
      </div>
    ));
  };

  // ---------------------- UI ----------------------
  return (
    <div style={{ display: "flex", gap: 16 }}>
      <div style={{ flex: 1 }}>
        <UserProfileCard token={token} setMsg={setMsg} me={admin} showPoints={false} />
        <AchievementsPanel token={token} me={{ points: reports?.adminPoints || 0 }} role="user" setMsg={setMsg} />

        <h3>Admin Reports</h3>

        {/* ---------- QUICK LOAD BUTTONS FIXED ---------- */}
        <button onClick={() => loadData("/api/actions/ngos", setNgos, "ngos")}>View Registered NGOs</button>
        <button style={{ marginLeft: 8 }} onClick={() => loadData("/api/actions/registered-events", setEvents, "events")}>
          View Registered Events
        </button>
        <button style={{ marginLeft: 8 }} onClick={() => { setEventStatsType("stats"); loadData("/api/actions/event-stats", setEventStats); }}>
          View Event Stats
        </button>

        {eventStats && (
          <div style={{ marginTop: 20 }}>
            <h4>Results</h4>
            {renderResults(eventStats, eventStatsType)}
          </div>
        )}

        {ngos && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {ngos.map((n) => (
              <div key={n.id} style={{ padding: 8, background: "#fff", borderRadius: 8, marginBottom: 8, display: "flex", justifyContent: "space-between" }}>
                <div>
                  <strong>{n.name}</strong>
                  <div>{n.email}</div>
                </div>
                <button style={{ background: "red", color: "white", padding: 6, borderRadius: 6 }} onClick={() => deleteNgo(n.id)}>Remove</button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ---------------- RIGHT PANEL ---------------- */}
      <div style={{ width: 280, display: "flex", flexDirection: "column", gap: 16 }}>

        <div style={{ background: "#fffbe6", padding: 12, borderRadius: 10 }}>
          <h4>Quick Actions</h4>
          <button
            onClick={() => { setEventStatsType("topVolunteers"); loadData("/api/actions/top-volunteers", setEventStats, "top"); }}
            style={{ width: "100%", padding: 10, marginBottom: 8 }}
          >
            Top Volunteers
          </button>

          <button
            onClick={() => { setEventStatsType("topDonors"); loadData("/api/actions/top-donors", setEventStats, "top"); }}
            style={{ width: "100%", padding: 10, marginBottom: 8 }}
          >
            Top Donors
          </button>

          <button
            onClick={() => { setEventStatsType("badges"); loadData("/api/actions/badges", setEventStats, "badges"); }}
            style={{ width: "100%", padding: 10 }}
          >
            View Badges
          </button>
        </div>

      </div>
    </div>
  );
}
